function T2(str,o={}){const t=figma.createText();t.fontName={family:o.fam||'Roboto',style:o.style||'Regular'};t.characters=str;t.fontSize=o.size||13;t.fills=[S(o.color)];if(o.align){t.textAutoResize='NONE';t.textAlignHorizontal=o.align;t.resize(o.w,o.h||18);}t.name=o.name||str.slice(0,12);return t;}
function R2(w,h,color,r=0){const x=figma.createRectangle();x.resize(w,h);x.fills=[S(color)];if(r)x.cornerRadius=r;return x;}
function icon(id,parent,x,y,size,label,color){const i=figma.getNodeById(id).createInstance();i.resize(size,size);i.x=x;i.y=y;i.name=label||'icon';parent.appendChild(i);
(function w(n){if(n.type==='VECTOR')n.fills=[S(color)];if('children'in n)n.children.forEach(w);})(i);
if(Array.isArray(i.fills)&&i.fills.length&&i.fills[0].type==='SOLID'){const c=i.fills[0].color;if(c.r>0.9&&c.g>0.9&&c.b>0.9)i.fills=[];}
return i;}

