const WS=figma.root.children.find(p=>p.id==='8:2');
await figma.setCurrentPageAsync(WS);
function findKid(node,nm){if(node.name===nm)return node;if('children'in node){for(const ch of node.children){const r=findKid(ch,nm);if(r)return r;}}return null;}
const out=[];
function countReactions(node,acc){if(node.reactions&&node.reactions.length){acc.n+=node.reactions.length;acc.dest.push(node.reactions[0].actions[0].destinationId);}if('children'in node)node.children.forEach(c=>countReactions(c,acc));}
WS.children.forEach(n=>{
  if(/^\d\d_/.test(n.name)){
    const acc={n:0,dest:[]};countReactions(n,acc);
    out.push(n.name+' ['+n.id+']: '+acc.n+' links -> '+acc.dest.join(','));
  }
});
return JSON.stringify(out,null,1);

